from __future__ import annotations
import matplotlib.pyplot as plt

def allowed(prefix: str) -> bool:
    return "11" not in prefix

def main(depth: int = 7) -> None:
    fig, ax = plt.subplots(figsize=(12, 6))
    levels = [[""]]
    for n in range(depth):
        levels.append([p + b for p in levels[-1] for b in "01" if allowed(p + b)])
    positions: dict[str, tuple[float, float]] = {}
    for n, words in enumerate(levels):
        for i, word in enumerate(words):
            positions[word] = ((i + 1) / (len(words) + 1), -n)
            if word:
                x, y = positions[word]
                px, py = positions[word[:-1]]
                ax.plot([px, x], [py, y], color="#5b8ff9", lw=1)
            ax.text(*positions[word], word or "∅", ha="center", va="center", fontsize=7,
                    bbox={"boxstyle": "circle,pad=.2", "fc": "white", "ec": "#5b8ff9"})
    ax.set_title("Admissible Prefix Tree: the Branch 11 Is Always Pruned")
    ax.axis("off")
    plt.tight_layout(); plt.show()

if __name__ == "__main__": main()

